/* Base styles */
:root {
  --bg-main: #FFFFFF;
  --bg-card: #F8F9FA;
  --bg-header: #F1F3F5;
  --text-primary: #212529;
  --text-secondary: #6C757D;
  --border-color: #DEE2E6;
  --border-light: #E9ECEF;
  --coral-primary: #FF7F50;
  --tiffany-primary: #40E0D0;
  --shadow-md: 0 2px 8px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 4px 16px rgba(0, 0, 0, 0.15);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-main);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
  height: 100%;
}

.app {
  max-width: none;
  margin: 0;
  padding: 18px 0 18px 18px;
}

.app__header { margin-bottom: 14px; }
.app__title { margin: 0; font-size: 22px; font-weight: 800; letter-spacing: .2px; }
.app__subtitle { margin-top: 4px; color: var(--muted); font-size: 13px; }

.app__grid { display: flex; gap: 0; width: 100%; }
.app__grid > .card { flex: 1 1 0; min-width: 240px; overflow: auto; }

.resizer { width: 8px; cursor: col-resize; position: relative; user-select: none; touch-action: none; align-self: stretch; background: transparent; }
.resizer::after { content:''; position:absolute; top:0; bottom:0; left:3px; width:2px; background: var(--border); transition: background .15s ease; }
.resizer:hover::after { background: #9ca3af; }

.card { background:white; border:1px solid var(--border); border-radius: var(--radius); padding:12px; }
.card__title { font-weight:600; margin-bottom:10px; }
.card--stack > .divider { height:1px; background:var(--border); margin:12px 0; }

.hint { margin-top: 8px; color: var(--muted); font-size: 12px; }
.hint__code { background:#f3f4f6; padding:2px 6px; border-radius:8px; }

/* Downsized buttons (no hover/active change) */
button, .btn, [role="button"], .button {
  background: var(--primary-600);
  color:#fff;
  border:none;
  border-radius: var(--btn-radius);
  padding: var(--btn-py) var(--btn-px);
  font-weight:600;
  font-size: var(--btn-font-size);
  line-height:1.1;
  cursor:pointer;
}
button:hover, .btn:hover, [role="button"]:hover, .button:hover,
button:active, .btn:active, [role="button"]:active, .button:active {
  background: var(--primary-600);
  color: #fff;
}
button:disabled, .btn:disabled { opacity:.55; cursor:not-allowed; }

.card input[type="text"],
.card input[type="search"],
.card input[type="number"],
.card select,
.card textarea { width:100%; max-width:100%; display:block; }

.app__footer { margin-top:16px; color:var(--muted); font-size:12px; display:flex; gap:10px; align-items:center; border-top:1px solid var(--border); padding-top:12px; }

@media (max-width: 1023px) {
  .app { padding: 12px; }
  .app__grid { flex-direction: column; }
  .resizer { display: none; }
}


/* QueryBuilder fallback styles (when Tailwind classes are not present) */
.qb__input {
  width: 100%;
  max-width: 100%;
  display: block;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 12px;
  outline: none;
}

.qb__input:focus {
  box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.25);
}


/* Ensure QueryBuilder input doesn't collapse too narrow */
.qb { width: 100%; }
.qb__input { width: 100%; min-width: 420px; }
@media (min-width: 1024px) {
  .qb__input { min-width: 640px; }
}

import { SearchProvider } from './context/SearchContext.jsx';
import { MainLayout } from './components/Layout';
import './App.css';

export default function App() {
  console.log('[App] rendering...');
  return (
    <SearchProvider>
      <MainLayout />
    </SearchProvider>
  );
}

/* CenterPanel 模組樣式 */

.centerPanel {
  display: flex;
  flex-direction: column;
  height: 100%;
  background-color: var(--bg-main);
  border-right: 1px solid var(--border-color);
  overflow: hidden;
}

.panelHeader {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-card);
}

.panelTitle {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
}

.panelContent {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
}

/* Studies List 樣式 */
.studiesList {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.studyItem {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.studyItem:hover {
  border-color: var(--tiffany-primary);
  box-shadow: var(--shadow-md);
}

.studyItem.expanded {
  box-shadow: var(--shadow-lg);
  border-color: var(--coral-primary);
}

.studyHeader {
  padding: 1rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  background-color: var(--bg-card);
  transition: background-color 0.2s;
}

.studyHeader:hover {
  background-color: rgba(64, 224, 208, 0.05);
}

.studyTitle {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
  flex: 1;
  text-align: left;
}

.expandIcon {
  color: var(--coral-primary);
  font-weight: bold;
  flex-shrink: 0;
  margin-top: 0.2rem;
}

.studyMeta {
  padding: 0.75rem 1rem;
  background-color: rgba(255, 127, 80, 0.03);
  border-top: 1px solid var(--border-light);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 0.75rem;
  font-size: 0.9rem;
}

.metaItem {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.metaLabel {
  font-weight: 600;
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.metaValue {
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.studyDetails {
  padding: 1rem;
  border-top: 1px solid var(--border-light);
  background-color: rgba(64, 224, 208, 0.02);
}

.abstract {
  margin: 0 0 1rem 0;
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--text-primary);
  font-style: italic;
}

.studyLinks {
  display: flex;
  gap: 0.75rem;
  margin: 1rem 0;
  flex-wrap: wrap;
}

.pubmedLink,
.publicationLink {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.6rem 1rem;
  background-color: var(--tiffany-primary);
  color: var(--text-on-accent);
  border: none;
  border-radius: 4px;
  text-decoration: none;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 0.9rem;
}

.pubmedLink:hover,
.publicationLink:hover {
  background-color: var(--tiffany-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.pubmedLink:active,
.publicationLink:active {
  background-color: var(--tiffany-dark);
  transform: translateY(0);
}

.studyIds {
  padding-top: 1rem;
  border-top: 1px solid var(--border-light);
  font-size: 0.85rem;
  color: var(--text-secondary);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  word-break: break-all;
}

/* Empty State */
.emptyState {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 2rem;
  text-align: center;
  color: var(--text-secondary);
}

.emptyState p {
  margin: 0;
  font-size: 1rem;
}

/* Loading State */
.loadingContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 1rem;
  color: var(--text-secondary);
}

.spinner {
  width: 40px;
  height: 40px;
  border: 4px solid var(--border-color);
  border-top-color: var(--coral-primary);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* Pagination 樣式 */
.paginationContainer {
  padding: 1rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
}

.paginationBtn {
  padding: 0.5rem 0.75rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
  font-weight: 500;
  color: var(--text-primary);
}

.paginationBtn:hover:not(:disabled) {
  background-color: var(--tiffany-primary);
  border-color: var(--tiffany-primary);
  color: var(--text-on-accent);
}

.paginationBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.paginationBtn.active {
  background-color: var(--coral-primary);
  border-color: var(--coral-primary);
  color: var(--text-on-accent);
}

/* 響應式設計 */
@media (max-width: 1024px) {
  .studyMeta {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .centerPanel {
    border-right: none;
  }

  .studyMeta {
    grid-template-columns: 1fr;
  }

  .studyIds {
    grid-template-columns: 1fr;
  }

  .studyLinks {
    flex-direction: column;
  }

  .pubmedLink,
  .publicationLink {
    width: 100%;
    justify-content: center;
  }
}

/**
 * StudiesList Component
 * Displays search results with PubMed links
 * Adapted from NeurosynthSearch ResultsList
 */
import React, { useState } from 'react';
import { getPubMedUrl } from '../../utils/stats';
import styles from './CenterPanel.module.css';

export function StudiesList({ studies = [], isLoading = false }) {
  const [expandedId, setExpandedId] = useState(null);

  const toggleExpanded = (studyId) => {
    setExpandedId(expandedId === studyId ? null : studyId);
  };

  if (isLoading) {
    return (
      <div className={styles.loadingContainer}>
        <div className={styles.spinner}></div>
        <p>Loading studies...</p>
      </div>
    );
  }

  if (studies.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p>No studies found. Try a different search.</p>
      </div>
    );
  }

  return (
    <div className={styles.studiesList}>
      {studies.map((study) => {
        const isExpanded = expandedId === study.study_id;
        const pubmedUrl = getPubMedUrl(study.pubmed_id || study.id);

        return (
          <article
            key={study.study_id || study.id}
            className={`${styles.studyItem} ${isExpanded ? styles.expanded : ''}`}
          >
            <div
              className={styles.studyHeader}
              onClick={() => toggleExpanded(study.study_id || study.id)}
              role="button"
              tabIndex="0"
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  toggleExpanded(study.study_id || study.id);
                }
              }}
            >
              <h3 className={styles.studyTitle}>{study.title}</h3>
              <span className={styles.expandIcon}>
                {isExpanded ? '▼' : '▶'}
              </span>
            </div>

            <div className={styles.studyMeta}>
              <div className={styles.metaItem}>
                <span className={styles.metaLabel}>Authors:</span>
                <span className={styles.metaValue}>
                  {study.authors || 'N/A'}
                </span>
              </div>
              <div className={styles.metaItem}>
                <span className={styles.metaLabel}>Journal:</span>
                <span className={styles.metaValue}>
                  {study.journal || 'N/A'}
                </span>
              </div>
              <div className={styles.metaItem}>
                <span className={styles.metaLabel}>Year:</span>
                <span className={styles.metaValue}>
                  {study.year || 'N/A'}
                </span>
              </div>
            </div>

            {isExpanded && (
              <div className={styles.studyDetails}>
                <p className={styles.abstract}>
                  {study.abstract || 'No abstract available'}
                </p>
                <div className={styles.studyLinks}>
                  {pubmedUrl && (
                    <a
                      href={pubmedUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={styles.pubmedLink}
                    >
                      📄 View on PubMed
                    </a>
                  )}
                  {study.url && (
                    <a
                      href={study.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={styles.publicationLink}
                    >
                      🔗 Publication Link
                    </a>
                  )}
                </div>
                <div className={styles.studyIds}>
                  <div>
                    <strong>Study ID:</strong> {study.study_id || study.id}
                  </div>
                  {study.contrast_id && (
                    <div>
                      <strong>Contrast ID:</strong> {study.contrast_id}
                    </div>
                  )}
                </div>
              </div>
            )}
          </article>
        );
      })}
    </div>
  );
}

/**
 * MainLayout Component
 * Three-column layout: LeftPanel (trends) | CenterPanel (papers) | RightPanel (3D viewer)
 */
import React, { useCallback, useContext } from 'react';
import { SearchContext } from '../../context/SearchContext.jsx';
import { fetchStudies, fetchLocations, fetchHelp } from '../../utils/api';
import { formatTrendData, formatJournalData } from '../../utils/stats';
import { SearchContainer } from '../SearchBar';
import { LeftPanel } from '../LeftPanel';
import { StudiesList } from '../CenterPanel';
import { NiiViewer } from '../RightPanel';
import styles from './MainLayout.module.css';

export function MainLayout() {
  const {
    query,
    studies,
    setStudies,
    setLocations,
    setTrendData,
    setJournalData,
    setRelatedTerms,
    loading,
    setLoading,
    error,
    setError,
    setPage,
  } = useContext(SearchContext);

  const handleSearch = useCallback(
    async (searchQuery) => {
      if (!searchQuery || searchQuery.trim().length === 0) {
        setError('Please enter a search term');
        return;
      }

      setLoading(true);
      setError('');
      setPage(1);

      try {
        // Fetch studies
        const studiesResponse = await fetchStudies(searchQuery);
        // API returns { results: [...], count: number }
        const studiesArray = studiesResponse?.results || [];
        setStudies(studiesArray);

        // Calculate statistics
        if (studiesArray && studiesArray.length > 0) {
          // Trend data (year over time)
          const trendFormatted = formatTrendData(studiesArray);
          setTrendData(trendFormatted);

          // Journal data (top 20 journals)
          const journalFormatted = formatJournalData(studiesArray, 20);
          setJournalData(journalFormatted);
        } else {
          setError(`No studies found for "${searchQuery}". Try a different search term.`);
          setTrendData([]);
          setJournalData([]);
          setRelatedTerms([]);
        }

        // Fetch locations (for future use)
        try {
          const locationsData = await fetchLocations(searchQuery);
          setLocations(locationsData || []);
        } catch (err) {
          console.warn('Error fetching locations:', err);
        }

        // Fetch help/context (optional)
        try {
          await fetchHelp(searchQuery);
        } catch (err) {
          console.warn('Error fetching help:', err);
        }
      } catch (err) {
        setError(err.message || 'Search failed');
        setStudies([]);
        setTrendData([]);
        setJournalData([]);
      } finally {
        setLoading(false);
      }
    },
    [setStudies, setLocations, setTrendData, setJournalData, setRelatedTerms, setLoading, setError, setPage]
  );

  return (
    <div className={styles.mainLayout}>
      {/* Search Bar Header */}
      <header className={styles.header}>
        <SearchContainer onSearch={handleSearch} />
      </header>

      {/* Error Message */}
      {error && (
        <div className={styles.errorBanner}>
          <span>⚠️ {error}</span>
          <button
            className={styles.closeError}
            onClick={() => setError('')}
            aria-label="Close error"
          >
            ✕
          </button>
        </div>
      )}

      {/* Three-Column Layout */}
      <div className={styles.container}>
        <aside className={styles.leftColumn}>
          <LeftPanel />
        </aside>

        <main className={styles.centerColumn}>
          <div className={styles.panelContent}>
            <StudiesList studies={studies} isLoading={loading} />
          </div>
        </main>

        <aside className={styles.rightColumn}>
          <div className={styles.rightPanelWrapper}>
            <div className={styles.panelHeader}>
              <h2 className={styles.panelTitle}>🧠 Brain Map</h2>
            </div>
            <div className={styles.panelContent}>
              <NiiViewer query={query} />
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}

/* MainLayout 模組樣式 */

.mainLayout {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background-color: var(--bg-main);
  overflow: hidden;
}

.header {
  background-color: var(--bg-header);
  border-bottom: 2px solid var(--tiffany-dark);
  box-shadow: var(--shadow-md);
  flex-shrink: 0;
}

.errorBanner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem;
  background-color: rgba(255, 127, 80, 0.1);
  border-bottom: 2px solid var(--coral-primary);
  color: var(--coral-primary);
  font-weight: 500;
  flex-shrink: 0;
}

.closeError {
  background: none;
  border: none;
  color: var(--coral-primary);
  cursor: pointer;
  font-size: 1.2rem;
  padding: 0 0.5rem;
  transition: opacity 0.2s;
}

.closeError:hover {
  opacity: 0.7;
}

/* Three-Column Container */
.container {
  display: grid;
  grid-template-columns: 300px 1fr 350px;
  gap: 0;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

.leftColumn,
.centerColumn,
.rightColumn {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.leftColumn {
  background-color: var(--bg-card-light);
  border-right: 1px solid var(--border-color);
}

.centerColumn {
  background-color: var(--bg-main);
}

.rightColumn {
  background-color: var(--bg-card-light);
  border-left: 1px solid var(--border-color);
}

/* Right Panel Wrapper */
.rightPanelWrapper {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

.panelHeader {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-card);
  flex-shrink: 0;
}

.panelTitle {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.panelContent {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
}

/* 響應式設計 - 平板 */
@media (max-width: 1200px) {
  .container {
    grid-template-columns: 280px 1fr 300px;
  }
}

@media (max-width: 1024px) {
  .container {
    grid-template-columns: 1fr 1fr;
  }

  .leftColumn {
    border-right: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
  }

  .rightColumn {
    grid-column: 1 / -1;
    border-left: none;
    border-top: 1px solid var(--border-color);
    max-height: 300px;
  }
}

/* 響應式設計 - 手機 */
@media (max-width: 768px) {
  .mainLayout {
    height: auto;
  }

  .container {
    grid-template-columns: 1fr;
    height: auto;
  }

  .leftColumn,
  .centerColumn,
  .rightColumn {
    min-height: 400px;
    max-height: none;
  }

  .leftColumn {
    border-right: none;
    border-bottom: 1px solid var(--border-color);
  }

  .centerColumn {
    border-bottom: 1px solid var(--border-color);
  }

  .rightColumn {
    border-left: none;
    border-top: 1px solid var(--border-color);
  }

  .errorBanner {
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

/* Scrollbar Styling */
.container > * {
  scrollbar-width: thin;
  scrollbar-color: var(--border-color) var(--bg-main);
}

.container > *::-webkit-scrollbar {
  width: 8px;
}

.container > *::-webkit-scrollbar-track {
  background: var(--bg-main);
}

.container > *::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

.container > *::-webkit-scrollbar-thumb:hover {
  background: var(--border-dark);
}

/**
 * LeftPanel Component
 * Displays trend analysis and journal statistics
 */
import React, { useContext } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { SearchContext } from '../../context/SearchContext.jsx';
import styles from './LeftPanel.module.css';

export function LeftPanel() {
  const { trendData, journalData } = useContext(SearchContext);

  return (
    <div className={styles.leftPanel}>
      <div className={styles.panelHeader}>
        <h2 className={styles.panelTitle}>📊 Analytics</h2>
      </div>

      <div className={styles.panelContent}>
        {/* Trend Chart */}
        {trendData && trendData.length > 0 && (
          <div className={styles.chartContainer}>
            <h3 className={styles.chartTitle}>Publication Trend</h3>
            <ResponsiveContainer width="100%" height={250}>
              <LineChart data={trendData}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" />
                <XAxis dataKey="year" stroke="var(--text-secondary)" />
                <YAxis stroke="var(--text-secondary)" />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'var(--bg-card)',
                    border: `1px solid var(--border-color)`,
                    borderRadius: '4px',
                  }}
                  labelStyle={{ color: 'var(--text-primary)' }}
                />
                <Legend wrapperStyle={{ color: 'var(--text-secondary)' }} />
                <Line
                  type="monotone"
                  dataKey="count"
                  stroke="var(--coral-primary)"
                  strokeWidth={2}
                  dot={{ fill: 'var(--coral-primary)', r: 4 }}
                  activeDot={{ r: 6 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Journal Chart */}
        {journalData && journalData.length > 0 && (
          <div className={styles.chartContainer}>
            <h3 className={styles.chartTitle}>Top Journals</h3>
            <ResponsiveContainer width="100%" height={250}>
              <BarChart
                data={journalData}
                layout="vertical"
                margin={{ top: 5, right: 30, left: 150, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" />
                <XAxis type="number" stroke="var(--text-secondary)" />
                <YAxis
                  dataKey="journal"
                  type="category"
                  stroke="var(--text-secondary)"
                  width={140}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'var(--bg-card)',
                    border: `1px solid var(--border-color)`,
                    borderRadius: '4px',
                  }}
                  labelStyle={{ color: 'var(--text-primary)' }}
                />
                <Bar dataKey="count" fill="var(--tiffany-primary)" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}

        {!trendData && !journalData && (
          <div className={styles.emptyState}>
            <p>📭 No data yet</p>
            <p style={{ fontSize: '0.9rem' }}>Search for a term to see analytics</p>
          </div>
        )}
      </div>
    </div>
  );
}

