  padding: 12px 20px;
  border-top: none;
  background: #f8fffe;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.relatedTitle {
  font-size: 12px;
  font-weight: 600;
  color: #2c3e50;
  margin: 0;
  white-space: nowrap;
}

.relatedTags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  flex: 1;
}

.relatedTag {
  padding: 6px 12px;
  background: #40E0D0;
  color: white;
  border: none;
  border-radius: 16px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.relatedTag:hover {
  background: #00CED1;
  transform: scale(1.02);
}

/* Additional class names used by RelatedTermsTags component */
.relatedTagsContainer {
  width: 100%;
  padding-top: 0.5rem;
  border-top: 1px solid var(--border-color, #e9ecef);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.relatedTagsLabel {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary, #6c757d);
  margin: 0;
}

.tagScore {
  background-color: rgba(0, 0, 0, 0.12);
  color: white;
  padding: 0 6px;
  margin-left: 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 700;
  display: inline-block;
}

/* Loading Indicator */
.loadingIndicator {
  text-align: center;
  padding: 20px;
  color: #FF7F50;
  font-size: 14px;
  animation: breathe 2s ease-in-out infinite;
}

@keyframes breathe {
  0%, 100% {
    opacity: 0.4;
  }
  50% {
    opacity: 1;
  }
}

/* Error State */
.errorMessage {
  padding: 12px 15px;
  background: #ffe8e8;
  border: 1px solid #ff7f7f;
  border-radius: 6px;
  color: #c33;
  font-size: 13px;
  margin-bottom: 12px;
}

/* Responsive */
@media (max-width: 768px) {
  .headerRow {
    flex-direction: column;
    border-bottom: 1px solid #ecf0f1;
  }

  .logoSection {
    width: 100%;
    border-right: none;
    border-bottom: 3px solid #40E0D0;
  }

  .operatorGroup {
    width: 100%;
  }

  .operatorButton {
    flex: 1;
  }

  .searchRow {
    padding: 10px 16px;
  }

  .searchInput {
    height: 36px;
    font-size: 13px;
  }

  .relatedPanel {
    padding: 10px 16px;
  }

  .relatedTitle {
    font-size: 11px;
  }

  .relatedTag {
    padding: 5px 10px;
    font-size: 11px;
  }
}

@media (max-width: 480px) {
  .logoSection {
    padding: 10px 12px;
    gap: 8px;
  }

  .logoImage {
    height: 40px;
  }

  .main {
    font-size: 14px;
  }

  .sub {
    font-size: 9px;
  }

  .operatorButton {
    padding: 10px 8px;
    font-size: 11px;
  }

  .searchRow {
    padding: 8px 12px;
    gap: 8px;
  }

  .searchInput {
    height: 36px;
    font-size: 12px;
    padding: 8px 10px;
  }

  .relatedPanel {
    padding: 8px 12px;
    gap: 8px;
  }

  .relatedTitle {
    font-size: 10px;
  }

  .relatedTag {
    padding: 4px 8px;
    font-size: 10px;
  }
}

/* Scrollbar Styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f1f1;
}

::-webkit-scrollbar-thumb {
  background: #40E0D0;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #00CED1;
}

/**
 * SearchContainer Component
 * Complete search integration with keyboard navigation
 * Copied and adapted from NeurosynthSearch/index.js
 */
import React, { useContext, useEffect, useState, useRef, useCallback } from 'react';
import { useDebounce } from '../../hooks';
import { SearchContext } from '../../context/SearchContext.jsx';
import { fetchTerms, fetchRelatedTerms } from '../../utils/api';
import { SearchInput, AutocompletePopup, LogicOperatorButtons, RelatedTermsTags } from './index';
import styles from './SearchBar.module.css';

const OPERATORS = ['AND', 'OR', 'NOT'];

export function SearchContainer({ onSearch }) {
  const { query, setQuery, relatedTerms, setRelatedTerms, setLoading } = useContext(SearchContext);

  // Suggestion state
  const [suggestions, setSuggestions] = useState([]);
  const [selectedSuggestionIndex, setSelectedSuggestionIndex] = useState(-1);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [allTerms, setAllTerms] = useState([]);

  // Operator state
  const [showOperatorChooser, setShowOperatorChooser] = useState(false);
  const [operatorIndex, setOperatorIndex] = useState(0);
  const [cursorAfterSpace, setCursorAfterSpace] = useState(0);

  // Related terms state
  const [relatedLoading, setRelatedLoading] = useState(false);

  const inputRef = useRef(null);
  const termsLoadedRef = useRef(false);
  const debouncedQuery = useDebounce(query, 250);

  // Load all terms on mount
  useEffect(() => {
    if (termsLoadedRef.current) return;

    setLoading(true);
    fetchTerms()
      .then((data) => {
        const termsArray = Array.isArray(data) ? data : (data?.terms || []);
        setAllTerms(termsArray);
        termsLoadedRef.current = true;
      })
      .catch((err) => {
        console.error('[SearchContainer] Error loading terms:', err);
        setAllTerms([]);
      })
      .finally(() => setLoading(false));
  }, [setLoading]);

  // Auto-search and load related terms when query changes (debounced)
  useEffect(() => {
    const trimmedQuery = debouncedQuery.trim();

    // Auto-trigger search when query is not empty
    if (trimmedQuery.length > 0) {
      console.log('[SearchContainer] Auto-searching for:', trimmedQuery);
      onSearch?.(trimmedQuery);
    }

    // Load related terms if query is a single complete word
    if (trimmedQuery.length > 0 && !trimmedQuery.includes(' ') && 
        !OPERATORS.some(op => trimmedQuery.toUpperCase().includes(op))) {
      setRelatedLoading(true);
      fetchRelatedTerms(trimmedQuery)
        .then((data) => {
          const related = Array.isArray(data) ? data : (data?.related || []);
          // Sort by co_count descending, take top 10
          const sorted = related
            .sort((a, b) => (b.co_count || 0) - (a.co_count || 0))
            .slice(0, 10);
          setRelatedTerms(sorted);
        })
        .catch((err) => {
          console.error('[SearchContainer] Error loading related terms:', err);
          setRelatedTerms([]);
        })
        .finally(() => setRelatedLoading(false));
    } else {
      setRelatedTerms([]);
    }
  }, [debouncedQuery, setRelatedTerms, onSearch]);

  // Filter suggestions based on current cursor position
  const updateSuggestions = useCallback(() => {
    if (!inputRef.current) return;

    const cursorPos = inputRef.current.selectionStart || 0;
    const textBeforeCursor = query.substring(0, cursorPos);

    // Get the last word before cursor
    const lastSpace = Math.max(
      textBeforeCursor.lastIndexOf(' '),
      textBeforeCursor.lastIndexOf('('),
      textBeforeCursor.lastIndexOf(')')
    );

    const lastWord = textBeforeCursor.substring(lastSpace + 1).trim();
    const isOperator = OPERATORS.some(op => op.startsWith(lastWord.toUpperCase()));

    // Check if we should show operator chooser (after space with incomplete operator)
    const shouldShowOperator = lastSpace >= 0 && 
                               lastSpace < cursorPos - 1 && 
                               !isOperator &&
                               lastWord.length > 0 &&
                               lastWord.length < 3; // Still typing operator

    if (shouldShowOperator) {
      setShowOperatorChooser(true);
      setCursorAfterSpace(lastSpace + 1);
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    setShowOperatorChooser(false);

    // Filter terms for autocomplete
    if (lastWord.length < 1) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    const queryLower = lastWord.toLowerCase();
    const filtered = allTerms
      .filter((term) => {
        const termStr = typeof term === 'string' ? term : term?.term || '';
        return termStr.toLowerCase().startsWith(queryLower);
      })
      .slice(0, 10)
      .map((term) => (typeof term === 'string' ? term : term?.term || ''));

    setSuggestions(filtered);
    setShowSuggestions(filtered.length > 0);
    setSelectedSuggestionIndex(-1);
  }, [query, allTerms]);

  // Update suggestions when query changes
  useEffect(() => {
    updateSuggestions();
  }, [debouncedQuery, updateSuggestions]);

  // Handle keyboard navigation
  const handleKeyDown = useCallback((e) => {
    if (showOperatorChooser) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setOperatorIndex((idx) => (idx + 1) % OPERATORS.length);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setOperatorIndex((idx) => (idx - 1 + OPERATORS.length) % OPERATORS.length);
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const operator = OPERATORS[operatorIndex];
        const textBeforeCursor = query.substring(0, cursorAfterSpace);
        const textAfterCursor = query.substring(cursorAfterSpace);
        setQuery(`${textBeforeCursor}${operator} ${textAfterCursor}`);
        setShowOperatorChooser(false);
        setTimeout(() => {
          if (inputRef.current) {
            const newPos = cursorAfterSpace + operator.length + 1;
            inputRef.current.setSelectionRange(newPos, newPos);
            inputRef.current.focus();
          }
        }, 0);
      } else if (e.key === 'Escape') {
        setShowOperatorChooser(false);
      }
    } else if (showSuggestions && suggestions.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedSuggestionIndex((idx) =>
          idx < suggestions.length - 1 ? idx + 1 : 0
        );
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedSuggestionIndex((idx) =>
          idx > 0 ? idx - 1 : suggestions.length - 1
        );
      } else if (e.key === 'Enter' && selectedSuggestionIndex >= 0) {
        e.preventDefault();
        const selected = suggestions[selectedSuggestionIndex];
        if (inputRef.current) {
          const cursorPos = inputRef.current.selectionStart || 0;
          const textBeforeCursor = query.substring(0, cursorPos);
          const textAfterCursor = query.substring(cursorPos);

          const lastSpace = Math.max(
            textBeforeCursor.lastIndexOf(' '),
            textBeforeCursor.lastIndexOf('('),
            textBeforeCursor.lastIndexOf(')')
          );

          const beforeLastSpace = textBeforeCursor.substring(0, lastSpace + 1);
          const newQuery = `${beforeLastSpace}${selected} ${textAfterCursor}`.trim();
          setQuery(newQuery);
        }

        setSuggestions([]);
        setShowSuggestions(false);
        setSelectedSuggestionIndex(-1);
      } else if (e.key === 'Escape') {
        setShowSuggestions(false);
      }
    } else if (e.key === 'Enter' && query.trim().length > 0) {
      e.preventDefault();
      onSearch?.(query.trim());
      setSuggestions([]);
      setShowSuggestions(false);
    }
  }, [
    showOperatorChooser,
    showSuggestions,
    suggestions,
    selectedSuggestionIndex,
    operatorIndex,
    query,
    cursorAfterSpace,
    setQuery,
    onSearch,
  ]);

  const handleSuggestionSelect = (term) => {
    if (inputRef.current) {
      const cursorPos = inputRef.current.selectionStart || 0;
      const textBeforeCursor = query.substring(0, cursorPos);
      const textAfterCursor = query.substring(cursorPos);

      const lastSpace = Math.max(
        textBeforeCursor.lastIndexOf(' '),
        textBeforeCursor.lastIndexOf('('),
        textBeforeCursor.lastIndexOf(')')
      );

      const beforeLastSpace = textBeforeCursor.substring(0, lastSpace + 1);
      const newQuery = `${beforeLastSpace}${term} ${textAfterCursor}`.trim();
      setQuery(newQuery);
    }

    setSuggestions([]);
    setShowSuggestions(false);
    setSelectedSuggestionIndex(-1);
  };

  const handleRelatedTermClick = (term) => {
    setQuery(term);
    // Don't auto-search, let user press Enter
    setSuggestions([]);
    setShowSuggestions(false);
  };

  return (
    <div className={styles.searchContainer}>
      {/* Header Row: Logo + Operators */}
      <div className={styles.headerRow}>
        {/* Logo Section */}
        <div className={styles.logoSection}>
          {/* Use BASE_URL so the path respects Vite `base` (works on GitHub Pages project sites) */}
          <img src={`${import.meta.env.BASE_URL}LoTUS-BF_logo.png`} alt="LoTUS-BF" className={styles.logoImage} />
          <div className={styles.logoText}>
            <span className={styles.main}>LoTUS-BF</span>
            <span className={styles.sub}>Location-or-Term Unified Search</span>
          </div>
        </div>

        {/* Operator Buttons */}
        <div className={styles.operatorGroup}>
          <LogicOperatorButtons />
        </div>
      </div>

      {/* Search Row */}
      <div className={styles.searchRow}>
        <div className={styles.searchInputWrapper}>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Enter search terms..."
            className={styles.searchInput}
            aria-label="Search with operators"
            aria-autocomplete="list"
            aria-controls="autocompletePopup"
          />

          <AutocompletePopup
            suggestions={suggestions}
            visible={showSuggestions && suggestions.length > 0 && !showOperatorChooser}
            selectedIndex={selectedSuggestionIndex}
            onSelect={handleSuggestionSelect}
            onHover={setSelectedSuggestionIndex}
            prefix={query.substring(Math.max(
              query.lastIndexOf(' '),
              query.lastIndexOf('('),
              query.lastIndexOf(')')
            ) + 1)}
          />
        </div>

        {/* keep spacing for any extra controls on the right of search row */}
        <div style={{ width: 24 }} />
      </div>

      {/* Related Terms Row */}
      {relatedTerms && relatedTerms.length > 0 && (
        <div className={styles.relatedPanel}>
          <span className={styles.relatedTitle}>Related terms:</span>
          <div className={styles.relatedTags}>
            <RelatedTermsTags 
              terms={relatedTerms} 
              onTermClick={handleRelatedTermClick}
              loading={relatedLoading}
            />
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * SearchInput Component
 * Advanced search input with logic operators for LoTUS-BF
 * Adapted from NeurosynthSearch TermInput
 */
import React, { useRef } from 'react';
import { useContext } from 'react';
import { SearchContext } from '../../context/SearchContext.jsx';
import styles from './SearchBar.module.css';

export function SearchInput({
  placeholder = 'Enter search terms with operators (AND, OR, NOT)...',
  onSearch,
}) {
  const inputRef = useRef(null);
  const { query, setQuery } = useContext(SearchContext);

  const handleChange = (e) => {
    const value = e.target.value;
    setQuery(value);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      // Trigger search with current query
      if (query && query.trim().length > 0) {
        onSearch?.(query.trim());
      }
    }
  };

  const handleFocus = () => {
    // Optional: Show suggestions on focus
  };

  return (
    <div className={styles.searchInputWrapper}>
      <input
        ref={inputRef}
        type="text"
        value={query}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onFocus={handleFocus}
        placeholder={placeholder}
        className={styles.searchInput}
        aria-label="Search with operators"
        aria-autocomplete="list"
        aria-controls="autocompletePopup"
      />
      <span className={styles.searchIcon}>🔍</span>
    </div>
  );
}

export { SearchInput } from './SearchInput';
export { AutocompletePopup } from './AutocompletePopup';
export { LogicOperatorButtons } from './LogicOperatorButtons';
export { RelatedTermsTags } from './RelatedTermsTags';
export { SearchContainer } from './SearchContainer';

import { API_BASE } from '../api'
import { useEffect, useMemo, useState } from 'react'

function classNames (...xs) { return xs.filter(Boolean).join(' ') }

export function Studies ({ query }) {
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState('')
  const [sortKey, setSortKey] = useState('year')
  const [sortDir, setSortDir] = useState('desc') // 'asc' | 'desc'
  const [page, setPage] = useState(1)
  const pageSize = 20

  useEffect(() => { setPage(1) }, [query])

  useEffect(() => {
    if (!query) return
    let alive = true
    const ac = new AbortController()
    ;(async () => {
      setLoading(true)
      setErr('')
      try {
        const url = `${API_BASE}/query/${encodeURIComponent(query)}/studies`
        const res = await fetch(url, { signal: ac.signal })
        const data = await res.json().catch(() => ({}))
        if (!res.ok) throw new Error(data?.error || `HTTP ${res.status}`)
        if (!alive) return
        const list = Array.isArray(data?.results) ? data.results : []
        setRows(list)
      } catch (e) {
        if (!alive) return
        setErr(`Unable to fetch studies: ${e?.message || e}`)
        setRows([])
      } finally {
        if (alive) setLoading(false)
      }
    })()
    return () => { alive = false; ac.abort() }
  }, [query])

  const changeSort = (key) => {
    if (key === sortKey) setSortDir(d => (d === 'asc' ? 'desc' : 'asc'))
    else { setSortKey(key); setSortDir('asc') }
  }

  const sorted = useMemo(() => {
    const arr = [...rows]
    const dir = sortDir === 'asc' ? 1 : -1
    arr.sort((a, b) => {
      const A = a?.[sortKey]
      const B = b?.[sortKey]
      // Numeric comparison for year; string comparison for other fields
      if (sortKey === 'year') return (Number(A || 0) - Number(B || 0)) * dir
      return String(A || '').localeCompare(String(B || ''), 'en') * dir
    })
    return arr
  }, [rows, sortKey, sortDir])

  const totalPages = Math.max(1, Math.ceil(sorted.length / pageSize))
  const pageRows = sorted.slice((page - 1) * pageSize, page * pageSize)

  return (
    <div className='flex flex-col rounded-2xl border'>
      <div className='flex items-center justify-between p-3'>
        <div className='card__title'>Studies</div>
        <div className='text-sm text-gray-500'>
           {/* {query ? `Query: ${query}` : 'Query: (empty)'} */}
        </div>
      </div>


      {query && loading && (
        <div className='grid gap-3 p-3'>
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className='h-10 animate-pulse rounded-lg bg-gray-100' />
          ))}
        </div>
      )}

      {query && err && (
        <div className='mx-3 mb-3 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700'>
          {err}
        </div>
      )}

      {query && !loading && !err && (
        <div className='overflow-auto'>
          <table className='min-w-full text-sm'>
            <thead className='sticky top-0 bg-gray-50 text-left'>
              <tr>
                {[
                  { key: 'year', label: 'Year' },
                  { key: 'journal', label: 'Journal' },
                  { key: 'title', label: 'Title' },
                  { key: 'authors', label: 'Authors' }
                ].map(({ key, label }) => (
                  <th key={key} className='cursor-pointer px-3 py-2 font-semibold' onClick={() => changeSort(key)}>
                    <span className='inline-flex items-center gap-2'>
                      {label}
                      <span className='text-xs text-gray-500'>{sortKey === key ? (sortDir === 'asc' ? '▲' : '▼') : ''}</span>
                    </span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {pageRows.length === 0 ? (
                <tr><td colSpan={4} className='px-3 py-4 text-gray-500'>No data</td></tr>
              ) : (
                pageRows.map((r, i) => (
                  <tr key={i} className={classNames(i % 2 ? 'bg-white' : 'bg-gray-50')}>
                    <td className='whitespace-nowrap px-3 py-2 align-top'>{r.year ?? ''}</td>
                    <td className='px-3 py-2 align-top'>{r.journal || ''}</td>
                    <td className='max-w-[540px] px-3 py-2 align-top'><div className='truncate' title={r.title}>{r.title || ''}</div></td>
                    <td className='px-3 py-2 align-top'>{r.authors || ''}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      {query && !loading && !err && (
        <div className='flex items-center justify-between border-t p-3 text-sm'>
          <div>Total <b>{sorted.length}</b> records, page <b>{page}</b>/<b>{totalPages}</b></div>
          <div className='flex items-center gap-2'>
            <button disabled={page <= 1} onClick={() => setPage(1)} className='rounded-lg border px-2 py-1 disabled:opacity-40'>⏮</button>
            <button disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))} className='rounded-lg border px-2 py-1 disabled:opacity-40'>Previous</button>
            <button disabled={page >= totalPages} onClick={() => setPage(p => Math.min(totalPages, p + 1))} className='rounded-lg border px-2 py-1 disabled:opacity-40'>Next</button>
            <button disabled={page >= totalPages} onClick={() => setPage(totalPages)} className='rounded-lg border px-2 py-1 disabled:opacity-40'>⏭</button>
          </div>
        </div>
      )}
    </div>
  )
}

import { API_BASE } from '../api'
import { useEffect, useMemo, useState } from 'react'

export function Terms ({ onPickTerm }) {
  const [terms, setTerms] = useState([])
  const [search, setSearch] = useState('')
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState('')

  useEffect(() => {
    let alive = true
    const ac = new AbortController()
    const load = async () => {
      setLoading(true)
      setErr('')
      try {
        const res = await fetch(`${API_BASE}/terms`, { signal: ac.signal })
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        const data = await res.json()
        if (!alive) return
        setTerms(Array.isArray(data?.terms) ? data.terms : [])
      } catch (e) {
        if (!alive) return
        setErr(`Failed to fetch terms: ${e?.message || e}`)
      } finally {
        if (alive) setLoading(false)
      }
    }
    load()
    return () => { alive = false; ac.abort() }
  }, [])

  const filtered = useMemo(() => {
    const s = search.trim().toLowerCase()
    if (!s) return terms
    return terms.filter(t => t.toLowerCase().includes(s))
  }, [terms, search])

  return (
    <div className='terms'>
      {/* Removed internal <h2> to avoid double "Terms" header. The bold title now comes from App.jsx card__title. */}

      <div className='terms__controls'>
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder='Search terms…'
          className='input'
        />
        <button
          onClick={() => setSearch('')}
          className='btn btn--primary'
        >
          Clear
        </button>
      </div>

      {loading && (
        <div className='terms__skeleton'>
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className='terms__skeleton-row' />
          ))}
        </div>
      )}

      {err && (
        <div className='alert alert--error'>
          {err}
        </div>
      )}

      {!loading && !err && (
        <div className='terms__list'>
          {filtered.length === 0 ? (
            <div className='terms__empty'>No terms found</div>
          ) : (
            <ul className='terms__ul'>
              {filtered.slice(0, 500).map((t, idx) => (
                <li key={`${t}-${idx}`} className='terms__li'>
                  <a
  href="#"
  className='terms__name'
  title={t}
  aria-label={`Add term ${t}`}
  onClick={(e) => { e.preventDefault(); onPickTerm?.(t); }}
>
  {t}
</a>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  )
}

/**
