        operator,
        setOperator,

        // 結果
        studies,
        setStudies,
        locations,
        setLocations,
        niiData,
        setNiiData,

        // UI
        loading,
        setLoading,
        error,
        setError,
        currentPage,
        setCurrentPage,
        setPage: setCurrentPage,
        totalCount,
        setTotalCount,

        // 建議
        relatedTerms,
        setRelatedTerms,
        suggestions,
        setSuggestions,

        // 趨勢
