        setTrendData,
        journalData,
        setJournalData,

        // 方法
        reset
      }}
    >
      {children}
    </SearchContext.Provider>
  );
};

/**
 * useDebounce Hook
 * Debounces a value and returns the debounced version
 */
import { useState, useEffect } from 'react';

export function useDebounce(value, delay = 250) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(handler);
  }, [value, delay]);

  return debouncedValue;
}

/**
 * useDebouncedCallback Hook
 * Debounces a callback function
 */
export function useDebouncedCallback(callback, delay = 250) {
  const [timeoutId, setTimeoutId] = useState(null);

  const debouncedCallback = (...args) => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    const newTimeoutId = setTimeout(() => {
      callback(...args);
    }, delay);
    setTimeoutId(newTimeoutId);
  };

  return debouncedCallback;
}

/**
 * useInfiniteScroll Hook
 * Handles infinite scroll functionality
 */
import { useState, useEffect, useRef } from 'react';
import { PAGINATION } from '../utils/constants';

export function useInfiniteScroll(items = [], batchSize = PAGINATION.BATCH_SIZE) {
  const [displayedItems, setDisplayedItems] = useState([]);
  const [hasMore, setHasMore] = useState(true);
  const sentinelRef = useRef(null);

  // Initialize with first batch
  useEffect(() => {
    if (items.length > 0) {
      setDisplayedItems(items.slice(0, batchSize));
      setHasMore(items.length > batchSize);
    }
  }, [items, batchSize]);

  // Setup intersection observer
  useEffect(() => {
    const currentSentinel = sentinelRef.current;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && hasMore) {
            // Load next batch
            setDisplayedItems((prev) => {
              const nextBatch = items.slice(
                prev.length,
                prev.length + batchSize
              );
              setHasMore(prev.length + nextBatch.length < items.length);
              return [...prev, ...nextBatch];
            });
          }
        });
      },
      {
        root: null,
        rootMargin: '200px',
        threshold: 0,
      }
    );

    if (currentSentinel) {
      observer.observe(currentSentinel);
    }

    return () => {
      if (currentSentinel) {
        observer.unobserve(currentSentinel);
      }
    };
  }, [items, hasMore, batchSize]);

  return {
    displayedItems,
    hasMore,
    sentinelRef,
  };
}

// src/hooks/useUrlQueryState.js
import { useCallback, useEffect, useMemo, useState } from 'react'

/**
 * Sync a string state with a URL query param (default: "q").
 * - Keeps other params intact
 * - Updates via history.replaceState (no page reload)
 * - Setter accepts value or updater function
 */
export function useUrlQueryState(param = 'q', initial = '') {
  // read once on mount
  const readFromUrl = useCallback(() => {
    const sp = new URLSearchParams(window.location.search)
    return sp.get(param) ?? initial
  }, [param, initial])

  const [value, setValue] = useState(readFromUrl)

  // keep internal state in sync if user uses back/forward
  useEffect(() => {
    const onPop = () => setValue(readFromUrl())
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [readFromUrl])

  // stable setter: updates state + URL
  const setAndSync = useCallback((next) => {
    setValue(prev => {
      const v = typeof next === 'function' ? next(prev) : next
      const url = new URL(window.location.href)
      const sp = url.searchParams
      if (v == null || v === '') sp.delete(param)
      else sp.set(param, String(v))
      // preserve hash/pathname; only replace search
      const newUrl = `${url.pathname}?${sp.toString()}${url.hash}`
      window.history.replaceState(null, '', newUrl)
      return v
    })
  }, [param])

  // memoized tuple (not strictly needed, but tidy)
  return useMemo(() => [value, setAndSync], [value, setAndSync])
}

export default useUrlQueryState

