const cache = {
  terms: new Map(),
  related: new Map(),
  studies: new Map(),
  locations: new Map(),
  nii: new Map(),
  timestamps: {
    terms: new Map(),
    related: new Map(),
    studies: new Map(),
    locations: new Map(),
    nii: new Map(),
  }
};

