/**
 * Pagination Component
 * Renders pagination controls
 */
import React from 'react';
import styles from './CenterPanel.module.css';

const MAX_VISIBLE_PAGES = 5;

export function Pagination({
  currentPage,
  totalCount,
  pageSize,
  onPageChange,
}) {
  const totalPages = Math.ceil(totalCount / pageSize);

  if (totalPages <= 1) {
    return null;
  }

  const handlePageClick = (page) => {
    if (page >= 1 && page <= totalPages) {
      onPageChange(page);
    }
  };

  const renderPageNumbers = () => {
    const pageNumbers = [];

    if (totalPages <= MAX_VISIBLE_PAGES + 2) {
      for (let i = 1; i <= totalPages; i++) {
        pageNumbers.push(i);
      }
    } else {
      pageNumbers.push(1);

      let startPage = Math.max(2, currentPage - Math.floor(MAX_VISIBLE_PAGES / 2));
      let endPage = Math.min(totalPages - 1, startPage + MAX_VISIBLE_PAGES - 1);

      if (endPage - startPage + 1 < MAX_VISIBLE_PAGES) {
        startPage = endPage - MAX_VISIBLE_PAGES + 1;
      }

      if (startPage > 2) {
        pageNumbers.push('...');
      }

      for (let i = startPage; i <= endPage; i++) {
        pageNumbers.push(i);
      }

      if (endPage < totalPages - 1) {
        pageNumbers.push('...');
      }

      pageNumbers.push(totalPages);
    }

    return pageNumbers.map((page, index) =>
      typeof page === 'number' ? (
        <button
          key={index}
          className={`${styles.paginationBtn} ${currentPage === page ? styles.active : ''}`}
          onClick={() => handlePageClick(page)}
          disabled={currentPage === page}
        >
          {page}
        </button>
      ) : (
        <span key={index} className={styles.paginationEllipsis}>
          {page}
        </span>
      )
    );
  };

  return (
    <div className={styles.paginationContainer}>
      <button
        className={styles.paginationBtn}
        onClick={() => handlePageClick(currentPage - 1)}
        disabled={currentPage === 1}
      >
        &laquo; Prev
      </button>
      {renderPageNumbers()}
      <button
        className={styles.paginationBtn}
        onClick={() => handlePageClick(currentPage + 1)}
        disabled={currentPage === totalPages}
      >
        Next &raquo;
      </button>
    </div>
  );
}

/**
 * CenterPanel Component
 * Encapsulates the studies list and pagination
 */
import React, { useContext } from 'react';
import { SearchContext } from '../../context/SearchContext.jsx';
import { StudiesList } from './StudiesList';
import { Pagination } from './Pagination';
import { PAGINATION } from '../../utils/constants';
import styles from './CenterPanel.module.css';

export function CenterPanel({ onPageChange }) {
  const {
    studies,
    loading,
    currentPage,
    totalCount,
  } = useContext(SearchContext);

  return (
    <div className={styles.centerPanel}>
      <div className={styles.panelContent}>
        <StudiesList studies={studies} isLoading={loading} />
      </div>
      <Pagination
        currentPage={currentPage}
        totalCount={totalCount}
        pageSize={PAGINATION.STUDIES_PER_PAGE}
        onPageChange={onPageChange}
      />
    </div>
  );
}

