/* CenterPanel 模組樣式 */

.centerPanel {
  display: flex;
  flex-direction: column;
  height: 100%;
  background-color: var(--bg-main);
  border-right: 1px solid var(--border-color);
}

.panelHeader {
  padding: 1rem;
  border-bottom: 1px solid var(--border-color);
  background-color: var(--bg-card);
}

.panelTitle {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
}

.panelContent {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
}

/* Studies List 樣式 */
.studiesList {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.studyItem {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.studyItem:hover {
  border-color: var(--tiffany-primary);
  box-shadow: var(--shadow-md);
}

.studyItem.expanded {
  box-shadow: var(--shadow-lg);
  border-color: var(--coral-primary);
}

.studyHeader {
  padding: 1rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  background-color: var(--bg-card);
  transition: background-color 0.2s;
}

.studyHeader:hover {
  background-color: rgba(64, 224, 208, 0.05);
}

.studyTitle {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
  flex: 1;
  text-align: left;
}

.expandIcon {
  color: var(--coral-primary);
  font-weight: bold;
  flex-shrink: 0;
  margin-top: 0.2rem;
}

.studyMeta {
  padding: 0.75rem 1rem;
  background-color: rgba(255, 127, 80, 0.03);
  border-top: 1px solid var(--border-light);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 0.75rem;
  font-size: 0.9rem;
}

.metaItem {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.metaLabel {
  font-weight: 600;
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.metaValue {
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.studyDetails {
  padding: 1rem;
  border-top: 1px solid var(--border-light);
  background-color: rgba(64, 224, 208, 0.02);
}

.abstract {
  margin: 0 0 1rem 0;
  font-size: 0.95rem;
  line-height: 1.5;
  color: var(--text-primary);
  font-style: italic;
}

.studyLinks {
  display: flex;
  gap: 0.75rem;
  margin: 1rem 0;
  flex-wrap: wrap;
}

.pubmedLink,
.publicationLink {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.6rem 1rem;
  background-color: var(--tiffany-primary);
  color: var(--text-on-accent);
  border: none;
  border-radius: 4px;
  text-decoration: none;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 0.9rem;
}

.pubmedLink:hover,
.publicationLink:hover {
  background-color: var(--tiffany-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.pubmedLink:active,
.publicationLink:active {
  background-color: var(--tiffany-dark);
  transform: translateY(0);
}

.studyIds {
  padding-top: 1rem;
  border-top: 1px solid var(--border-light);
  font-size: 0.85rem;
  color: var(--text-secondary);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  word-break: break-all;
}

/* Empty State */
.emptyState {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 2rem;
  text-align: center;
  color: var(--text-secondary);
}

.emptyState p {
  margin: 0;
  font-size: 1rem;
}

/* Loading State */
.loadingContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 1rem;
  color: var(--text-secondary);
}

.spinner {
  width: 40px;
  height: 40px;
  border: 4px solid var(--border-color);
  border-top-color: var(--coral-primary);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* Pagination 樣式 */
.paginationContainer {
  padding: 1rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
}

.paginationBtn {
  padding: 0.5rem 0.75rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
  font-weight: 500;
  color: var(--text-primary);
}

.paginationBtn:hover:not(:disabled) {
  background-color: var(--tiffany-primary);
  border-color: var(--tiffany-primary);
  color: var(--text-on-accent);
}

.paginationBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.paginationBtn.active {
  background-color: var(--coral-primary);
  border-color: var(--coral-primary);
  color: var(--text-on-accent);
}

/* 響應式設計 */
@media (max-width: 1024px) {
  .studyMeta {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .centerPanel {
    border-right: none;
  }

  .studyMeta {
    grid-template-columns: 1fr;
  }

  .studyIds {
    grid-template-columns: 1fr;
  }

  .studyLinks {
    flex-direction: column;
  }

  .pubmedLink,
  .publicationLink {
    width: 100%;
    justify-content: center;
  }
}

