      setLoading(true);
      setError('');
      setPage(1);

      try {
        // Fetch first page of studies
        const studiesResponse = await fetchStudies(searchQuery, PAGINATION.STUDIES_PER_PAGE, 0);
        const studiesArray = studiesResponse?.results || [];
        setStudies(studiesArray);
        setTotalCount(studiesResponse?.count || 0);

        // Calculate statistics
        if (studiesArray.length > 0) {
          const trendFormatted = formatTrendData(studiesArray);
          setTrendData(trendFormatted);

          const journalFormatted = formatJournalData(studiesArray, 20);
          setJournalData(journalFormatted);
        } else {
          setError(`No studies found for "${searchQuery}". Try a different search term.`);
          setTrendData([]);
          setJournalData([]);
          setRelatedTerms([]);
          setTotalCount(0);
        }

        // Fetch other data in parallel
        fetchLocations(searchQuery).then(setLocations).catch(err => console.warn('Error fetching locations:', err));
        fetchHelp(searchQuery).catch(err => console.warn('Error fetching help:', err));

      } catch (err) {
        setError(err.message || 'Search failed');
        setStudies([]);
        setTrendData([]);
        setJournalData([]);
        setTotalCount(0);
      } finally {
        setLoading(false);
      }
    },
    [setStudies, setLocations, setTrendData, setJournalData, setRelatedTerms, setLoading, setError, setPage, setTotalCount]
  );

  const handlePageChange = useCallback(async (newPage) => {
    setPage(newPage);
    setLoading(true);
    setError('');
    try {
      const offset = (newPage - 1) * PAGINATION.STUDIES_PER_PAGE;
      const studiesResponse = await fetchStudies(query, PAGINATION.STUDIES_PER_PAGE, offset);
      setStudies(studiesResponse?.results || []);
      // Total count should not change on pagination, so we don't set it here
    } catch (err) {
      setError(err.message || 'Failed to fetch page');
    } finally {
      setLoading(false);
    }
  }, [query, setPage, setLoading, setStudies, setError]);

  return (
    <div className={styles.mainLayout}>
      {/* Search Bar Header */}
      <header className={styles.header}>
        <SearchContainer onSearch={handleSearch} />
      </header>

      {/* Error Message */}
      {error && (
        <div className={styles.errorBanner}>
          <span>⚠️ {error}</span>
          <button
            className={styles.closeError}
            onClick={() => setError('')}
            aria-label="Close error"
          >
            ✕
          </button>
        </div>
      )}

      {/* Three-Column Layout */}
      <div className={styles.container}>
        <aside className={styles.leftColumn}>
          <LeftPanel />
        </aside>

        <main className={styles.centerColumn}>
          <CenterPanel onPageChange={handlePageChange} />
        </main>

        <aside className={styles.rightColumn}>
          <div className={styles.rightPanelWrapper}>
            <div className={styles.panelHeader}>
              <h2 className={styles.panelTitle}>🧠 Brain Map</h2>
            </div>
            <div className={styles.panelContent}>
              <NiiViewer query={query} />
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}

