/* SearchBar Module - LoTUS-BF Color Scheme */
/* Coral Red (#FF7F50) + Tiffany Blue (#40E0D0) */

.searchContainer {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 30px;
  background: white;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  /* allow autocomplete popup to overflow outside container */
  overflow: visible;
}

/* Top Row: Logo + Operators */
.headerRow {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0;
  background: white;
  border-bottom: 3px solid #40E0D0;
}

/* Logo Section */
.logoSection {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 20px;
  background: white;
  flex-shrink: 0;
  border-right: 1px solid #ecf0f1;
}

.logoImage {
  height: 50px;
  width: auto;
  flex-shrink: 0;
}

.logoText {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.main {
  font-size: 18px;
  font-weight: 700;
  color: #FF7F50;
  letter-spacing: 0.5px;
}

.sub {
  font-size: 10px;
  color: #40E0D0;
  font-weight: 500;
}

/* Operator Buttons */
.operatorGroup {
  display: flex;
  gap: 0;
  flex: 1;
}

.operatorButton {
  flex: 1;
  padding: 12px 16px;
  background: #FF7F50;
  border: none;
  border-right: 1px solid #ff6a35;
  border-radius: 0;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  color: white;
  text-align: center;
}

.operatorButton:last-child {
  border-right: none;
}

.operatorButton:hover {
  background: #FF6347;
  transform: none;
}

.operatorButton.active {
  background: #FF6347;
  color: white;
}

/* Search Row */
.searchRow {
  display: flex;
  gap: 10px;
  align-items: stretch;
  padding: 12px 20px;
  background: white;
  border-bottom: 1px solid #ecf0f1;
}

.searchInputWrapper {
  position: relative; /* anchor for autocomplete popup */
  flex: 1;
  display: flex;
  align-items: center;
}

.searchInput {
  flex: 1;
  padding: 10px 14px;
  border: 1px solid #e0e0e0;
  border-radius: 4px;
  font-size: 14px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  outline: none;
  transition: all 0.3s ease;
  background: white;
  color: #2c3e50;
  height: 40px;
}

.searchInput::placeholder {
  color: #bdc3c7;
}

.searchInput:focus {
  border-color: #40E0D0;
  box-shadow: 0 0 0 2px rgba(64, 224, 208, 0.1);
}

.searchButton {
  display: none;
}

/* Suggestions Container */
.suggestionsContainer {
  position: static;
  margin: 8px 0 0 0;
  width: 100%;
}

/* Autocomplete popup positioning (render under the input) */
.autocompletePopup {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  width: 100%;
  max-width: 720px;
  z-index: 1200;
  box-shadow: 0 6px 18px rgba(0,0,0,0.12);
  border-radius: 6px;
  background: white;
}

.suggestionsList {
  max-height: 320px;
  overflow-y: auto;
}

.suggestionsList {
  list-style: none;
  border: 1px solid #ecf0f1;
  border-radius: 6px;
  background: white;
  max-height: 300px;
  overflow-y: auto;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  margin: 0;
  padding: 0;
}

.suggestionItem {
  padding: 10px 15px;
  cursor: pointer;
  border-bottom: 1px solid #ecf0f1;
  transition: all 0.15s ease;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: #2c3e50;
}

.suggestionItem:last-child {
  border-bottom: none;
}

.suggestionItem:hover {
  background: #f0fffe;
  color: #FF7F50;
}

.suggestionItem.focused {
  background: #FF7F50;
  color: white;
}

.suggestionText {
  flex: 1;
}

.suggestionText strong {
  font-weight: 600;
  color: inherit;
}

/* Related Terms Panel */
.relatedPanel {
  margin-top: 0;
  padding: 12px 20px;
  border-top: none;
  background: #f8fffe;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.relatedTitle {
  font-size: 12px;
  font-weight: 600;
  color: #2c3e50;
  margin: 0;
  white-space: nowrap;
}

.relatedTags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  flex: 1;
}

.relatedTag {
  padding: 6px 12px;
  background: #40E0D0;
  color: white;
  border: none;
  border-radius: 16px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.relatedTag:hover {
  background: #00CED1;
  transform: scale(1.02);
}

/* Additional class names used by RelatedTermsTags component */
.relatedTagsContainer {
  width: 100%;
  padding-top: 0.5rem;
  border-top: 1px solid var(--border-color, #e9ecef);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.relatedTagsLabel {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary, #6c757d);
  margin: 0;
}

.tagScore {
  background-color: rgba(0, 0, 0, 0.12);
  color: white;
  padding: 0 6px;
  margin-left: 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 700;
  display: inline-block;
}

/* Loading Indicator */
.loadingIndicator {
  text-align: center;
  padding: 20px;
  color: #FF7F50;
  font-size: 14px;
  animation: breathe 2s ease-in-out infinite;
}

@keyframes breathe {
  0%, 100% {
    opacity: 0.4;
  }
  50% {
    opacity: 1;
  }
}

/* Error State */
.errorMessage {
  padding: 12px 15px;
  background: #ffe8e8;
  border: 1px solid #ff7f7f;
  border-radius: 6px;
  color: #c33;
  font-size: 13px;
  margin-bottom: 12px;
}

/* Responsive */
@media (max-width: 768px) {
  .headerRow {
    flex-direction: column;
    border-bottom: 1px solid #ecf0f1;
  }

  .logoSection {
    width: 100%;
    border-right: none;
    border-bottom: 3px solid #40E0D0;
  }

  .operatorGroup {
    width: 100%;
  }

  .operatorButton {
    flex: 1;
  }

  .searchRow {
    padding: 10px 16px;
  }

  .searchInput {
    height: 36px;
    font-size: 13px;
  }

  .relatedPanel {
    padding: 10px 16px;
  }

  .relatedTitle {
    font-size: 11px;
  }

  .relatedTag {
    padding: 5px 10px;
    font-size: 11px;
  }
}

@media (max-width: 480px) {
  .logoSection {
    padding: 10px 12px;
    gap: 8px;
  }

  .logoImage {
    height: 40px;
  }

  .main {
    font-size: 14px;
  }

  .sub {
    font-size: 9px;
  }

  .operatorButton {
    padding: 10px 8px;
    font-size: 11px;
  }

  .searchRow {
    padding: 8px 12px;
    gap: 8px;
  }

  .searchInput {
    height: 36px;
    font-size: 12px;
    padding: 8px 10px;
  }

  .relatedPanel {
    padding: 8px 12px;
    gap: 8px;
  }

  .relatedTitle {
    font-size: 10px;
  }

  .relatedTag {
    padding: 4px 8px;
    font-size: 10px;
  }
}

/* Scrollbar Styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f1f1;
}

::-webkit-scrollbar-thumb {
  background: #40E0D0;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #00CED1;
}

