/**
 * SearchContainer Component
 * Complete search integration with full keyboard navigation.
 */
import React, { useContext, useEffect, useState, useRef, useCallback } from 'react';
import { useDebounce } from '../../hooks';
import { SearchContext } from '../../context/SearchContext.jsx';
import { fetchTerms, fetchRelatedTerms } from '../../utils/api';
import { AutocompletePopup, LogicOperatorButtons, RelatedTermsTags } from './index';
import styles from './SearchBar.module.css';

const OPERATORS = ['AND', 'OR', 'NOT'];

export function SearchContainer({ onSearch }) {
  const { query, setQuery, relatedTerms, setRelatedTerms, setLoading } = useContext(SearchContext);

  // Autocomplete state
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [allTerms, setAllTerms] = useState([]);
  const [relatedLoading, setRelatedLoading] = useState(false);

  // Keyboard navigation state
  const [activeSection, setActiveSection] = useState('input'); // 'input', 'logic', 'related'
  const [focusedLogicIndex, setFocusedLogicIndex] = useState(-1);
  const [focusedRelatedIndex, setFocusedRelatedIndex] = useState(-1);

  const inputRef = useRef(null);
  const termsLoadedRef = useRef(false);
  const debouncedQuery = useDebounce(query, 250);

  const insertText = useCallback((text) => {
    if (!inputRef.current) return;
    const input = inputRef.current;
    const start = input.selectionStart;
    const end = input.selectionEnd;
    const newQuery = query.substring(0, start) + text + query.substring(end);
    setQuery(newQuery);
    setTimeout(() => {
      input.focus();
      const newCursorPos = start + text.length;
      input.setSelectionRange(newCursorPos, newCursorPos);
    }, 0);
  }, [query, setQuery]);

  // Load all terms on mount
  useEffect(() => {
    if (termsLoadedRef.current) return;
    setLoading(true);
    fetchTerms()
      .then((data) => {
        const termsArray = Array.isArray(data) ? data : (data?.terms || []);
        setAllTerms(termsArray);
        termsLoadedRef.current = true;
      })
      .catch((err) => console.error('[SearchContainer] Error loading terms:', err))
      .finally(() => setLoading(false));
  }, [setLoading]);

  // Auto-search and load related terms when query changes
  useEffect(() => {
    const trimmedQuery = debouncedQuery.trim();
    if (trimmedQuery) onSearch?.(trimmedQuery);

    if (trimmedQuery && !trimmedQuery.includes(' ') && !OPERATORS.some(op => trimmedQuery.toUpperCase().includes(op))) {
      setRelatedLoading(true);
      fetchRelatedTerms(trimmedQuery)
        .then((data) => {
          const related = Array.isArray(data) ? data : (data?.related || []);
          setRelatedTerms(related.sort((a, b) => (b.co_count || 0) - (a.co_count || 0)).slice(0, 10));
        })
        .catch(() => setRelatedTerms([]))
        .finally(() => setRelatedLoading(false));
    } else {
      setRelatedTerms([]);
    }
  }, [debouncedQuery, setRelatedTerms, onSearch]);

  const handleRelatedTermClick = (term) => {
    const cursorPos = inputRef.current.selectionStart || 0;
    const textBeforeCursor = query.substring(0, cursorPos);
    const lastSpace = Math.max(textBeforeCursor.lastIndexOf(' '), textBeforeCursor.lastIndexOf('('), textBeforeCursor.lastIndexOf(')'));
    const beforeLastSpace = textBeforeCursor.substring(0, lastSpace + 1);
    const newQuery = `${beforeLastSpace}${term} `;
    setQuery(newQuery);
    setShowSuggestions(false);
    setTimeout(() => inputRef.current.focus(), 0);
  };

  const handleOperatorClick = (op) => {
    insertText(` ${op} `);
  };

  // Main keyboard navigation logic
  const handleKeyDown = useCallback((e) => {
    if (activeSection === 'input') {
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveSection('logic');
        setFocusedLogicIndex(0);
      } else if (e.key === 'ArrowDown') {
        if (relatedTerms.length > 0) {
          e.preventDefault();
          setActiveSection('related');
          setFocusedRelatedIndex(0);
        }
      }
    } 
  }, [activeSection, relatedTerms.length]);

  // Listener for when focus is on button groups
  useEffect(() => {
    const handleNavKeyDown = (e) => {
      if (activeSection === 'logic') {
        e.preventDefault();
        if (e.key === 'ArrowRight') {
          setFocusedLogicIndex(prev => (prev + 1) % OPERATORS.length);
        } else if (e.key === 'ArrowLeft') {
          setFocusedLogicIndex(prev => (prev - 1 + OPERATORS.length) % OPERATORS.length);
        } else if (e.key === 'Enter') {
          insertText(` ${OPERATORS[focusedLogicIndex]} `);
        } else if (e.key === 'ArrowDown' || e.key === 'Escape') {
          setActiveSection('input');
          setFocusedLogicIndex(-1);
          inputRef.current.focus();
        }
      } else if (activeSection === 'related') {
        e.preventDefault();
        if (e.key === 'ArrowRight') {
          setFocusedRelatedIndex(prev => (prev + 1) % relatedTerms.length);
        } else if (e.key === 'ArrowLeft') {
          setFocusedRelatedIndex(prev => (prev - 1 + relatedTerms.length) % relatedTerms.length);
        } else if (e.key === 'Enter') {
          handleRelatedTermClick(relatedTerms[focusedRelatedIndex].term);
        } else if (e.key === 'ArrowUp' || e.key === 'Escape') {
          setActiveSection('input');
          setFocusedRelatedIndex(-1);
          inputRef.current.focus();
        }
      }
    };

    if (activeSection !== 'input') {
      document.addEventListener('keydown', handleNavKeyDown);
    } else {
      document.removeEventListener('keydown', handleNavKeyDown);
    }

    return () => document.removeEventListener('keydown', handleNavKeyDown);
  }, [activeSection, focusedLogicIndex, focusedRelatedIndex, relatedTerms, insertText, handleRelatedTermClick]);


  return (
    <div className={styles.searchContainer}>
      {/* Left Column */}
      <div className={styles.logoWrapper}>
        <img src={`${import.meta.env.BASE_URL}LoTUS-BF_logo.png`} alt="LoTUS-BF Logo" className={styles.logoImage} />
        <div className={styles.logoTextWrapper}>
          <h1 className={styles.logoTitle}>LoTUS-BF</h1>
          <p className={styles.logoSubtitle}>Location-or-Term Unified Search for Brain Functions</p>
        </div>
      </div>

      {/* Right Column */}
      <div className={styles.searchControls}>
        <div className={styles.operatorGroup}>
          <LogicOperatorButtons onOperatorClick={handleOperatorClick} focusedIndex={focusedLogicIndex} />
        </div>

        <div className={styles.searchInputWrapper}>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            onFocus={() => setActiveSection('input')}
            placeholder="Enter search term, e.g., amygdala AND fear"
            className={styles.searchInput}
          />
          {query && (
            <button onClick={() => setQuery('')} className={styles.clearButton} aria-label="Clear search">×</button>
          )}
          {/* Autocomplete popup is disabled for simplicity while keyboard nav is active */}
        </div>

        <div className={styles.relatedTagsContainer}>
          <span className={styles.relatedTagsLabel}>Related terms:</span>
          <RelatedTermsTags 
            terms={relatedTerms} 
            onTermClick={handleRelatedTermClick}
            loading={relatedLoading}
            focusedIndex={focusedRelatedIndex}
          />
        </div>
      </div>
    </div>
  );
}

.searchInputWrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.searchInput {
  width: 100%;
  padding: 0.8rem 2.5rem 0.8rem 1rem; /* Add padding-right for clear button */
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 1rem;
  outline: none;
  transition: all 0.3s ease;
}

.clearButton {
  position: absolute;
  right: 0.8rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  font-size: 1.5rem;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 0;
  line-height: 1;
}
.clearButton:hover {
  color: var(--text-primary);
}


.searchInput:focus {
  border-color: var(--tiffany-primary);
  box-shadow: 0 0 0 3px rgba(64, 224, 208, 0.2);
}

/* Related Terms Tags */
.relatedTagsContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  overflow-x: auto; /* Use horizontal scrolling */
  flex-wrap: nowrap;   /* Use horizontal scrolling */
  padding-bottom: 4px;
  scrollbar-width: thin;
  min-height: 28px; /* Reserve space to prevent layout shift */
  position: relative; /* Create stacking context */
}

.relatedTagsLabel {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  flex-shrink: 0;
  white-space: nowrap;
}

.relatedTag {
  padding: 0.25rem 0.7rem;
  background-color: #E0F2F1; /* Light teal background */
  color: #00796B; /* Dark teal text */
  border: 1px solid #B2DFDB; /* Teal border */
  border-radius: 16px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  position: relative; /* For hover indicator */
}

.relatedTag:hover,
.relatedTag.focused {
  background-color: #B2DFDB;
  box-shadow: 0 0 0 2px var(--tag-success-light);
}

.relatedTag::before {
  content: '▲';
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  transition: all 0.2s ease;
  color: var(--tag-success-dark);
  font-size: 0.8rem;
  pointer-events: none;
  z-index: 10;
}

.relatedTag:hover::before {
  opacity: 1;
  bottom: 140%;
}

/* Autocomplete Popup */
.autocompletePopup {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  width: 100%;
  z-index: 1200;
  box-shadow: 0 6px 18px rgba(0,0,0,0.12);
  border-radius: 6px;
  background: white;
  border: 1px solid var(--border-light);
}

