            placeholder="Enter search term, e.g., amygdala AND fear"
            className={styles.searchInput}
          />
          {query && <button onClick={() => setQuery('')} className={styles.clearButton}>×</button>}
        </div>

        <div className={styles.relatedTagsContainer}>
          <span className={styles.relatedTagsLabel}>Related terms:</span>
          <RelatedTermsTags 
            terms={relatedTerms} 
            onTermClick={handleRelatedTermClick}
            loading={relatedLoading}
            focusedIndex={activeSection === 'related' ? focusedIndex : -1}
          />
        </div>

        <AutocompletePopup
          suggestions={suggestions}
          visible={showSuggestions && activeSection !== 'related' && activeSection !== 'logic'}
          selectedIndex={activeSection === 'autocomplete' ? focusedIndex : -1}
          onSelect={handleSuggestionSelect}
          onHover={(i) => { setActiveSection('autocomplete'); setFocusedIndex(i); }}
          prefix={query.substring(query.lastIndexOf(' ') + 1)}
        />
      </div>
    </div>
  );
}

.searchInputWrapper {
  position: relative;
  display: flex;
  align-items: center;
  z-index: 10;
}

.searchInput {
  width: 100%;
  padding: 0.8rem 2.5rem 0.8rem 1rem; /* Add padding-right for clear button */
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 1rem;
  outline: none;
  transition: all 0.3s ease;
}

.clearButton {
  position: absolute;
  right: 0.8rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  font-size: 1.5rem;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 0;
  line-height: 1;
}
.clearButton:hover {
  color: var(--text-primary);
}


.searchInput:focus {
  border-color: var(--tiffany-primary);
  box-shadow: 0 0 0 3px rgba(64, 224, 208, 0.2);
}

/* Related Terms Tags */
.relatedTagsContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  overflow-x: auto; /* Use horizontal scrolling */
  flex-wrap: nowrap;   /* Use horizontal scrolling */
  padding-bottom: 4px;
  scrollbar-width: thin;
  min-height: 28px; /* Reserve space to prevent layout shift */
  position: relative; /* Create stacking context */
}

.relatedTagsLabel {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
  flex-shrink: 0;
  white-space: nowrap;
}

.relatedTag {
  padding: 0.25rem 0.7rem;
  background-color: #E0F2F1; /* Light teal background */
  color: #00796B; /* Dark teal text */
  border: 1px solid #B2DFDB; /* Teal border */
  border-radius: 16px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  position: relative; /* For hover indicator */
}

.relatedTag:hover,
.relatedTag.focused {
  background-color: #B2DFDB;
  box-shadow: 0 0 0 2px var(--tag-success-light);
}

.relatedTag::before {
  content: '▲';
  position: absolute;
  bottom: 120%;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  transition: all 0.2s ease;
  color: var(--tag-success-dark);
  font-size: 0.8rem;
  pointer-events: none;
  z-index: 10;
}

.relatedTag:hover::before {
  opacity: 1;
  bottom: 140%;
}

