.autocompletePopup {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  width: 100%;
  z-index: 1200;
  box-shadow: 0 6px 18px rgba(0,0,0,0.12);
  border-radius: 6px;
  background: white;
  border: 1px solid var(--border-light);
}

