/**
 * SearchContainer Component
 * Final complete refactor with unified keyboard navigation and correct stacking context.
 */
import React, { useContext, useEffect, useState, useRef, useCallback } from 'react';
import { useDebounce } from '../../hooks';
import { SearchContext } from '../../context/SearchContext.jsx';
import { fetchTerms, fetchRelatedTerms } from '../../utils/api';
import { OPERATORS } = from '../../utils/constants';
import { AutocompletePopup, LogicOperatorButtons, RelatedTermsTags } from './index';
import styles from './SearchBar.module.css';

export function SearchContainer({ onSearch }) {
  const { query, setQuery, relatedTerms, setRelatedTerms, setLoading } = useContext(SearchContext);

  const [allTerms, setAllTerms] = useState([]);
  const [relatedLoading, setRelatedLoading] = useState(false);

  // Unified state for all popups and keyboard navigation
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [activeSection, setActiveSection] = useState('input'); // 'input', 'logic', 'related', 'autocomplete'
  const [focusedIndex, setFocusedIndex] = useState(-1);

  const inputRef = useRef(null);
  const termsLoadedRef = useRef(false);
  const debouncedQuery = useDebounce(query, 250);

  // --- Data Fetching ---
  useEffect(() => {
    if (termsLoadedRef.current) return;
    setLoading(true);
    fetchTerms()
      .then(data => { setAllTerms(Array.isArray(data) ? data : (data?.terms || [])); termsLoadedRef.current = true; })
      .catch(err => console.error('[SearchContainer] Error loading terms:', err))
      .finally(() => setLoading(false));
  }, [setLoading]);

  useEffect(() => {
    const trimmedQuery = debouncedQuery.trim();
    if (trimmedQuery) onSearch?.(trimmedQuery);

    const operatorLabels = OPERATORS.map(op => op.label);
    if (trimmedQuery && !trimmedQuery.includes(' ') && !operatorLabels.some(op => trimmedQuery.toUpperCase().includes(op))) {
      setRelatedLoading(true);
      fetchRelatedTerms(trimmedQuery)
        .then(data => setRelatedTerms((Array.isArray(data) ? data : (data?.related || [])).sort((a, b) => (b.co_count || 0) - (a.co_count || 0)).slice(0, 10)))
        .catch(() => setRelatedTerms([]))
        .finally(() => setRelatedLoading(false));
    } else {
      setRelatedTerms([]);
    }

    const lastWord = query.substring(query.lastIndexOf(' ') + 1);
    if (lastWord && activeSection === 'input') {
      const filtered = allTerms.filter(t => t.toLowerCase().startsWith(lastWord.toLowerCase())).slice(0, 10);
      setSuggestions(filtered);
      setShowSuggestions(filtered.length > 0);
    } else {
      setShowSuggestions(false);
    }
  }, [debouncedQuery, query, allTerms, setRelatedTerms, onSearch, activeSection]);

  // --- Text Insertion & Click Handlers ---
  const insertText = useCallback((text, { replace = false } = {}) => {
    if (!inputRef.current) return;
    const input = inputRef.current;
    const start = input.selectionStart;
    const currentQuery = query;
    let newQuery, newCursorPos;

    if (replace) {
      const lastSpace = Math.max(currentQuery.substring(0, start).lastIndexOf(' '), currentQuery.substring(0, start).lastIndexOf('('), currentQuery.substring(0, start).lastIndexOf(')'));
      const before = currentQuery.substring(0, lastSpace + 1);
      newQuery = `${before}${text} `;
      newCursorPos = newQuery.length;
    } else {
      newQuery = currentQuery.substring(0, start) + text + currentQuery.substring(start);
      newCursorPos = start + text.length;
    }

    setQuery(newQuery);
    setTimeout(() => {
      input.focus();
      input.setSelectionRange(newCursorPos, newCursorPos);
    }, 0);
  }, [query, setQuery]);

  const handleOperatorClick = (op) => insertText(` ${op} `);
  const handleRelatedTermClick = (term) => insertText(term, { replace: true });
  const handleSuggestionSelect = (term) => {
    insertText(term, { replace: true });
    setShowSuggestions(false);
    setActiveSection('input');
  };

  // --- Keyboard Navigation --- 
  const handleGlobalKeyDown = useCallback((e) => {
    if (activeSection === 'input') return;
    e.preventDefault();

    const keyMap = {
      logic: {
        ArrowRight: () => setFocusedIndex(p => (p + 1) % OPERATORS.length),
        ArrowLeft: () => setFocusedIndex(p => (p - 1 + OPERATORS.length) % OPERATORS.length),
        Enter: () => focusedIndex > -1 && insertText(` ${OPERATORS[focusedIndex].label} `),
        ArrowDown: () => { setActiveSection('input'); inputRef.current.focus(); },
        Escape: () => { setActiveSection('input'); inputRef.current.focus(); },
      },
      related: {
        ArrowRight: () => setFocusedIndex(p => (p + 1) % relatedTerms.length),
        ArrowLeft: () => setFocusedIndex(p => (p - 1 + relatedTerms.length) % relatedTerms.length),
        Enter: () => focusedIndex > -1 && handleRelatedTermClick(relatedTerms[focusedIndex].term),
        ArrowUp: () => { setActiveSection('input'); inputRef.current.focus(); },
        Escape: () => { setActiveSection('input'); inputRef.current.focus(); },
      },
      autocomplete: {
        ArrowDown: () => setFocusedIndex(p => (p + 1) % suggestions.length),
        ArrowUp: () => setFocusedIndex(p => (p - 1 + suggestions.length) % suggestions.length),
        Enter: () => focusedIndex > -1 && handleSuggestionSelect(suggestions[focusedIndex]),
        Escape: () => {
          setActiveSection('input');
          setShowSuggestions(false);
        },
      },
    };

    keyMap[activeSection]?.[e.key]?.();

  }, [activeSection, focusedIndex, suggestions, relatedTerms, insertText, handleRelatedTermClick, handleSuggestionSelect]);

  useEffect(() => {
    document.addEventListener('keydown', handleGlobalKeyDown);
    return () => document.removeEventListener('keydown', handleGlobalKeyDown);
  }, [handleGlobalKeyDown]);

  const handleInputKeyDown = (e) => {
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveSection('logic');
      setFocusedIndex(0);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (showSuggestions) {
        setActiveSection('autocomplete');
        setFocusedIndex(0);
      } else if (relatedTerms.length > 0) {
        setActiveSection('related');
        setFocusedIndex(0);
      }
    }
  };

  return (
    <div className={styles.searchContainer}>
      <div className={styles.logoWrapper}>
        <img src={`${import.meta.env.BASE_URL}LoTUS-BF_logo.png`} alt="LoTUS-BF Logo" className={styles.logoImage} />
        <div className={styles.logoTextWrapper}>
          <h1 className={styles.logoTitle}>LoTUS-BF</h1>
          <p className={styles.logoSubtitle}>Location-or-Term Unified Search for Brain Functions</p>
        </div>
      </div>

      <div className={styles.searchControls}>
        <div className={styles.operatorGroup}>
          <LogicOperatorButtons onOperatorClick={handleOperatorClick} focusedIndex={activeSection === 'logic' ? focusedIndex : -1} />
        </div>

        <div className={styles.searchInputWrapper}>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleInputKeyDown}
            onFocus={() => setActiveSection('input')}
            placeholder="Enter search term, e.g., amygdala AND fear"
            className={styles.searchInput}
          />
          {query && <button onClick={() => setQuery('')} className={styles.clearButton}>×</button>}
        </div>

        <div className={styles.relatedTagsContainer}>
          <span className={styles.relatedTagsLabel}>Related terms:</span>
          <RelatedTermsTags 
            terms={relatedTerms} 
            onTermClick={handleRelatedTermClick}
            loading={relatedLoading}
            focusedIndex={activeSection === 'related' ? focusedIndex : -1}
          />
        </div>

        <AutocompletePopup
          suggestions={suggestions}
          visible={showSuggestions}
          selectedIndex={activeSection === 'autocomplete' ? focusedIndex : -1}
          onSelect={handleSuggestionSelect}
          onHover={(i) => { setActiveSection('autocomplete'); setFocusedIndex(i); }}
          prefix={query.substring(query.lastIndexOf(' ') + 1)}
        />
      </div>
    </div>
  );
}
